<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(17, 24, 39, 0.9);
      --panel-strong: #111827;
      --text: #e5e7eb;
      --muted: #9ca3af;
      --line: rgba(148, 163, 184, 0.16);
      --accent: #ef4444;
      --accent-hover: #f87171;
      --button: #1f2937;
      --button-hover: #374151;
      --shadow: 0 24px 70px rgba(0, 0, 0, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.18), transparent 35%),
        radial-gradient(circle at 80% 20%, rgba(236, 72, 153, 0.12), transparent 28%),
        var(--bg);
      color: var(--text);
      padding: 24px;
    }

    .page {
      width: min(760px, 100%);
      display: grid;
      gap: 18px;
    }

    .card {
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.92), rgba(15, 23, 42, 0.88));
      border: 1px solid var(--line);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .preview {
      padding: 20px;
      display: grid;
      gap: 16px;
    }

    .image-frame {
      position: relative;
      border-radius: 20px;
      overflow: hidden;
      background: #0f172a;
      border: 1px solid rgba(255, 255, 255, 0.06);
    }

    .image-frame img {
      display: block;
      width: 100%;
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    .meta {
      display: flex;
      align-items: start;
      justify-content: space-between;
      gap: 12px;
      flex-wrap: wrap;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.35rem, 2vw, 1.8rem);
      letter-spacing: -0.02em;
    }

    p {
      margin: 6px 0 0;
      color: var(--muted);
      line-height: 1.55;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
    }

    button {
      font: inherit;
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.25rem;
      cursor: pointer;
      transition: transform 160ms ease, background-color 160ms ease, border-color 160ms ease, opacity 160ms ease;
    }

    button:focus-visible {
      outline: 3px solid rgba(96, 165, 250, 0.9);
      outline-offset: 3px;
    }

    .trigger {
      background: linear-gradient(180deg, #ef4444, #dc2626);
      color: white;
      box-shadow: 0 12px 30px rgba(220, 38, 38, 0.28);
    }

    .trigger:hover {
      background: linear-gradient(180deg, var(--accent-hover), #ef4444);
      transform: translateY(-1px);
    }

    dialog {
      width: min(92vw, 520px);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 24px;
      padding: 0;
      background: rgba(15, 23, 42, 0.98);
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(2, 6, 23, 0.72);
      backdrop-filter: blur(10px);
    }

    .dialog-content {
      padding: 24px;
    }

    .dialog-title {
      margin: 0 0 8px;
      font-size: 1.35rem;
      letter-spacing: -0.02em;
    }

    .dialog-copy {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      margin-top: 24px;
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      flex-wrap: wrap;
    }

    .secondary {
      background: var(--button);
      color: var(--text);
      border: 1px solid rgba(255, 255, 255, 0.07);
    }

    .secondary:hover {
      background: var(--button-hover);
      transform: translateY(-1px);
    }

    .danger {
      background: linear-gradient(180deg, #f87171, #ef4444);
      color: white;
    }

    .danger:hover {
      background: linear-gradient(180deg, #fb7185, #f43f5e);
      transform: translateY(-1px);
    }

    @media (max-width: 540px) {
      .preview,
      .dialog-content {
        padding: 18px;
      }

      .actions,
      .dialog-actions {
        justify-content: stretch;
      }

      .actions button,
      .dialog-actions button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="card preview" aria-labelledby="image-title">
      <div class="image-frame">
        <img
          alt="A moody blue-toned abstract image preview"
          src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1600 1000'%3E%3Cdefs%3E%3CradialGradient id='g1' cx='50%25' cy='35%25' r='70%25'%3E%3Cstop offset='0%25' stop-color='%232563eb'/%3E%3Cstop offset='55%25' stop-color='%231e293b'/%3E%3Cstop offset='100%25' stop-color='%230f172a'/%3E%3C/radialGradient%3E%3ClinearGradient id='g2' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop offset='0%25' stop-color='%23fb7185' stop-opacity='.85'/%3E%3Cstop offset='100%25' stop-color='%2393c5fd' stop-opacity='.05'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1600' height='1000' fill='url(%23g1)'/%3E%3Ccircle cx='1220' cy='210' r='240' fill='url(%23g2)'/%3E%3Ccircle cx='350' cy='760' r='270' fill='%230b1120' fill-opacity='.7'/%3E%3Cpath d='M120 690C340 520 490 810 720 680s310-290 510-160 240 170 250 190v290H120z' fill='%23111d36' fill-opacity='.95'/%3E%3Cpath d='M280 315c110-80 180-40 260 50 85 97 170 140 280 106 120-36 190-141 320-154 111-10 235 60 340 198v136H280z' fill='%23203a5d' fill-opacity='.92'/%3E%3C/svg%3E"
        />
      </div>
      <div class="meta">
        <div>
          <h1 id="image-title">Image preview</h1>
          <p>Review the image before removing it from your library.</p>
        </div>
      </div>
      <div class="actions">
        <button type="button" class="trigger" id="open-dialog">Delete image</button>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <form method="dialog" class="dialog-content">
      <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
      <p class="dialog-copy" id="dialog-description">
        This will permanently remove the image from your library. You can’t undo this action.
      </p>
      <div class="dialog-actions">
        <button type="submit" value="cancel" class="secondary">Cancel</button>
        <button type="submit" value="delete" class="danger">Delete</button>
      </div>
    </form>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const openButton = document.getElementById('open-dialog');

    openButton.addEventListener('click', () => {
      dialog.showModal();
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue === 'delete') {
        openButton.textContent = 'Deleted';
        openButton.disabled = true;
        openButton.style.opacity = '0.75';
        openButton.style.cursor = 'default';
      }
    });
  </script>
</body>
</html>
